exercise.solution:
function ProfileCard({ name, role, skills }) {
  return (
    <article className="profile-card">
      <h2>{name}</h2>
      <p className="role">{role}</p>
      {skills.length > 0 ? (
        <ul>
          {skills.map(skill => (
            <li key={skill}>{skill}</li>
          ))}
        </ul>
      ) : (
        <p className="no-skills">No skills yet</p>
      )}
    </article>
  );
}

function App() {
  return (
    <>
      <ProfileCard
        name="Anna"
        role="Frontend developer"
        skills={["React", "CSS"]}
      />
      <ProfileCard
        name="Bence"
        role="Backend developer"
        skills={[]}
      />
    </>
  );
}

